package com.arcclaw.app.structured;

import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

import com.arcclaw.core.structured.StructuredOutputEngine;

import io.quarkus.test.junit.QuarkusTest;
import jakarta.inject.Inject;

@QuarkusTest
public class StructuredOutputEngineSchemaTest {

    @Inject
    StructuredOutputEngine engine;

    @Test
    void testSchemaLoading() {
        // SynthesisFunction.json should be generated by AgentFunctionProcessor
        String schema = engine.invokeSchemaLoadingForTest("SynthesisFunction");
        
        assertNotNull(schema, "Schema should not be null");
        assertNotEquals("{}", schema, "Schema should not be the generic {} fallback");
        assertTrue(schema.contains("contributions"), "Schema should contain 'contributions' field");
        assertTrue(schema.contains("conflictSummary"), "Schema should contain 'conflictSummary' field");
        assertTrue(schema.contains("finalResolution"), "Schema should contain 'finalResolution' field");
        assertTrue(schema.contains("additionalInfo"), "Schema should contain 'additionalInfo' field");
    }
}
